import { useEffect } from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';

// images
import LogoDark from '../../assets/images/K3_Logo-removebg.png';
import LogoLight from '../../assets/images/K3_Logo-removebg.png';

type AccountLayoutProps = {
    hasLogo?: boolean;
    bottomLinks?: any;
    children?: React.ReactNode;
};

const AuthLayout = ({ hasLogo, bottomLinks, children }: AccountLayoutProps) => {
    const { t } = useTranslation();

    useEffect(() => {
        if (document.body) {
            document.body.classList.add('authentication-bg');
        }
        return () => {
            if (document.body) {
                document.body.classList.remove('authentication-bg');
            }
        };
    }, []);

    return (
        <div className="account-pages my-5">
            <Container>
                <Row className="justify-content-center">
                    <Col md={8} lg={6} xl={4}>
                        {hasLogo && (
                            <div className="text-center">
                                <div className="auth-logo">
                                    {/* <Link to="/" className="logo logo-dark text-center">
                                        <span className="logo-lg">
                                            <img src={LogoDark} alt="" width="150" />
                                        </span>
                                    </Link> */}

                                    <Link to="/" className="logo logo-light text-center">
                                        <span className="logo-lg">
                                            <img src={LogoLight} alt="logo" width="150" />
                                        </span>
                                    </Link>
                                </div>
                                {/* <p className="text-muted mt-2 mb-4">{t('Responsive Admin Dashboard')}</p> */}
                            </div>
                        )}
                        <Card>
                            <Card.Body className="p-4" style={{ borderRadius: '5px' }}>
                                {children}
                            </Card.Body>
                            {bottomLinks}
                        </Card>

                        {/* bottom links */}
                    </Col>
                </Row>
            </Container>
        </div>
    );
};

AuthLayout.defaultProps = {
    hasLogo: true,
};

export default AuthLayout;
